const mongoose = require("mongoose");

const brochureChunkSchema = new mongoose.Schema(
  {
    brochure: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Brochure",
      required: true,
      index: true,
    },

    uploadedBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: true,
      index: true,
    },

    pageNumber: {
      type: Number,
      required: true,
    },

    chunkIndex: {
      type: Number,
      required: true,
    },

    text: {
      type: String,
      required: true,
    },

    // Numerical vector generated by Gemini
    embedding: {
      type: [Number],
      default: undefined,
      select: false,
    },
  },
  { timestamps: true },
);

brochureChunkSchema.index(
  { brochure: 1, pageNumber: 1, chunkIndex: 1 },
  { unique: true },
);

module.exports = mongoose.model("BrochureChunk", brochureChunkSchema);
